INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'am', 'በእስራኤልና በአጎራባች አካባቢዎች የሚገኙ የክርስትና ቅርስ ስፍራዎችን፣ ቅርሳ ቅርሶችንና የብራና መጻሕፍትን ፎቶግራፍ ለማንሳት፣ በስካነር ለመቅዳትና ለመሰነድ የተዘጋጀ ሁሉን አቀፍ ጅምር ነው። ይህ ዲጂታል ማኅደር ዋጋ የማይተመንላቸውን ታሪካዊ መዛግብት ለተመራማሪዎችና ለመጪው ትውልድ ይጠብቃል።', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'short_description', 'am', 'በመላው ቅድስት ምድር የሚገኙ የክርስትና ቅርስ ስፍራዎችን በዲጂታል መንገድ መሰነድ።', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
