INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'full_description', 'he', 'פרויקט זה מתמקד בצרכי השיקום הקריטיים של הבזיליקה, לרבות תיקונים קונסטרוקטיביים, ניקוי החזית ושימור האלמנטים האדריכליים המקוריים. העבודה תבטיח שהמבנה יישאר בטוח ונגיש לדורות הבאים.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
