INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project_update', '593f2031-2c23-4d15-86c5-7487a8296b4f', 'content', 'hi', 'संरचनात्मक मूल्यांकन का चरण सफलतापूर्वक पूरा हो गया है। इंजीनियरों ने उन मुख्य हिस्सों की पहचान कर ली है जिन पर ध्यान देने की आवश्यकता है।', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project_update', '593f2031-2c23-4d15-86c5-7487a8296b4f', 'title', 'hi', 'मूल्यांकन पूरा हुआ', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project_update', 'ee7631c8-fb98-4e45-b8ea-9fa78251cd23', 'content', 'hi', 'हमने उच्च-रिज़ॉल्यूशन फ़ोटोग्राफ़ी और 3D स्कैन के माध्यम से अपने पहले 50 विरासत स्थलों का सफलतापूर्वक दस्तावेज़ीकरण कर लिया है।', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project_update', 'ee7631c8-fb98-4e45-b8ea-9fa78251cd23', 'title', 'hi', 'पहले 50 स्थलों का दस्तावेज़ीकरण पूरा', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'category', 'hi', 'जीर्णोद्धार', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'full_description', 'hi', 'यह परियोजना महागिरजाघर के जीर्णोद्धार की सबसे ज़रूरी आवश्यकताओं पर केंद्रित है, जिनमें संरचनात्मक मरम्मत, अग्रभाग की सफ़ाई और मूल वास्तुशिल्पीय तत्वों का संरक्षण शामिल है। यह कार्य सुनिश्चित करेगा कि भवन आने वाली पीढ़ियों के लिए सुरक्षित और सुलभ बना रहे।', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'short_description', 'hi', 'घोषणा के महागिरजाघर के मुख्य मध्यभाग और अग्रभाग का जीर्णोद्धार।', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'title', 'hi', 'महागिरजाघर का जीर्णोद्धार - चरण 1', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'category', 'hi', 'दस्तावेज़ीकरण', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'hi', 'इस्राएल और आसपास के क्षेत्रों में मसीही विरासत स्थलों, प्राचीन वस्तुओं और पांडुलिपियों की तस्वीरें लेने, उन्हें स्कैन करने और उनका दस्तावेज़ीकरण करने की एक व्यापक पहल। यह डिजिटल अभिलेखागार अमूल्य ऐतिहासिक अभिलेखों को शोधकर्ताओं और आने वाली पीढ़ियों के लिए सुरक्षित रखेगा।', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'short_description', 'hi', 'पूरी पवित्र भूमि में फैले मसीही विरासत स्थलों का डिजिटल दस्तावेज़ीकरण।', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'title', 'hi', 'पवित्र भूमि की विरासत का दस्तावेज़ीकरण', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'hy', 'Ավետման բազիլիկը կաթոլիկ եկեղեցի է Իսրայելի Նազարեթ քաղաքում։ Այն Մերձավոր Արևելքի ամենամեծ եկեղեցիներից մեկն է և կանգնած է այն վայրում, որտեղ, ըստ ավանդության, Գաբրիել հրեշտակապետը Կույս Մարիամին ավետեց, որ նա պիտի ծնի Հիսուսին։', 'Ներկայիս բազիլիկը կառուցվել է 1969 թվականին՝ իտալացի ճարտարապետ Ջովաննի Մուցիոյի նախագծով։ Այն վեր է խոյանում բյուզանդական և խաչակրաց ժամանակաշրջանների ավելի վաղ եկեղեցիների ավերակների վրա։ Հնագույն ժամանակներից ի վեր այս վայրը գրավում է քրիստոնյա ուխտավորներին։', 'Եկեղեցին ծառայում է Նազարեթի տեղի կաթոլիկ համայնքին և հյուրընկալում է աշխարհի տարբեր ծայրերից եկած ուխտավորներին։ Պատարագները կանոնավոր կերպով մատուցվում են տարբեր լեզուներով։') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'hy', 'Բեթղեհեմի Սուրբ Ծննդյան տաճարը կանգնած է այն քարայրի վրա, որը քրիստոնեական ավանդությունը II դարից ի վեր մեծարում է որպես Հիսուսի ծննդավայր։ Այն աշխարհի ամենահին անընդմեջ գործող եկեղեցիներից մեկն է և ընդգրկված է ՅՈՒՆԵՍԿՕ-ի Համաշխարհային ժառանգության ցանկում։', 'Առաջին բազիլիկը կառուցվել է մ.թ. մոտ 327 թվականին՝ Կոստանդիանոս կայսեր և նրա մոր՝ Հեղինեի հրամանով։ VI դարում վնասվելուց հետո Հուստինիանոս կայսրն այն վերակառուցեց ավելի մեծ չափերով, և ներկայիս տաճարի զգալի մասը հենց այդ վերակառուցման ժամանակներից է։ Ներսում մինչ օրս պահպանվել են խաչակիրների դարաշրջանի խճանկարներ և նկարազարդ սյուներ։', 'Համաձայն պատմական Ստատուս քվոյի՝ տաճարը համատեղ տնօրինում են հույն ուղղափառ, հռոմեական կաթոլիկ (ֆրանցիսկյաններ) և հայ առաքելական համայնքները։ Բեթղեհեմի տեղացի քրիստոնյա ընտանիքներն այստեղ աղոթում են աշխարհի տարբեր ծայրերից եկած ուխտավորների հետ, հատկապես Սուրբ Ծննդյան տոներին։') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'hy', 'Երուսաղեմի Հին քաղաքում գտնվող Սուրբ Հարության տաճարն իր մեջ ներառում է քրիստոնեության երկու մեծագույն սրբավայրերը՝ Գողգոթան, որտեղ խաչվեց Հիսուսը, և Սուրբ Գերեզմանը, որտեղ, ըստ ավանդության, Նա թաղվեց և հարություն առավ։', 'Կոստանդիանոս կայսրն այստեղ առաջին եկեղեցին կառուցեց IV դարում, և այն օծվեց մ.թ. 335 թվականին։ 1009 թվականին տաճարն ավերվեց, XI դարում վերակառուցվեց, իսկ XII դարում խաչակիրներն էականորեն ձևավորեցին նրա ներկայիս տեսքը։ Սուրբ Գերեզմանի վրա կառուցված մատուռը վերականգնվեց 2016–2017 թվականներին։', 'Տաճարի խնամքը համատեղ իրականացնում են Հույն ուղղափառ, Հռոմեական կաթոլիկ (ֆրանցիսկյաններ) և Հայ առաքելական եկեղեցիները, իսկ իրենց մատուռներն ունեն նաև ղպտի, եթովպական և ասորի ուղղափառ համայնքները։ Այս կարգը սահմանված է 1852 թվականի Ստատուս քվոյով։ Տաճարի դռներն ամեն առավոտ բացում են մահմեդական ընտանիքները, որոնք դարեր շարունակ պահում են դրա բանալիները։') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
