INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project_update', '593f2031-2c23-4d15-86c5-7487a8296b4f', 'content', 'hy', 'Կառուցվածքային գնահատման փուլը հաջողությամբ ավարտվել է։ Ինժեներները բացահայտել են ուշադրություն պահանջող հիմնական հատվածները։', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
