INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'full_description', 'hy', 'Նախագիծը նպատակաուղղված է բազիլիկի վերականգնման հրատապ կարիքների բավարարմանը, այդ թվում՝ կառուցվածքային նորոգմանը, ճակատի մաքրմանն ու ճարտարապետական բնօրինակ տարրերի պահպանմանը։ Աշխատանքները կապահովեն շենքի անվտանգությունն ու հասանելիությունը գալիք սերունդների համար։', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'short_description', 'hy', 'Ավետման բազիլիկի գլխավոր նավի և ճակատի վերականգնում։', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
