INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'category', 'hy', 'Փաստագրում', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'hy', 'Համապարփակ նախաձեռնություն, որի նպատակն է լուսանկարել, սկանավորել և փաստագրել քրիստոնեական ժառանգության վայրերը, հնագույն առարկաներն ու ձեռագրերն Իսրայելում և հարակից տարածաշրջաններում։ Այս թվային արխիվը կպահպանի անգնահատելի պատմական վկայությունները հետազոտողների և գալիք սերունդների համար։', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'short_description', 'hy', 'Քրիստոնեական ժառանգության վայրերի թվային փաստագրում ողջ Սուրբ երկրում։', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'title', 'hy', 'Սուրբ երկրի ժառանգության փաստագրում', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'id', 'Basilika Kabar Sukacita adalah sebuah gereja Katolik di Nazaret, Israel. Gereja ini merupakan salah satu gereja terbesar di Timur Tengah dan menandai lokasi tradisional tempat Malaikat Agung Gabriel mengumumkan kepada Maria bahwa ia akan mengandung Yesus.', 'Basilika yang berdiri saat ini dibangun pada tahun 1969, dirancang oleh arsitek Italia Giovanni Muzio. Bangunan ini berdiri di atas reruntuhan gereja Bizantium dan era Perang Salib sebelumnya. Situs ini telah menjadi tempat ziarah Kristen sejak zaman kuno.', 'Gereja ini melayani komunitas Katolik setempat di Nazaret dan menyambut para peziarah dari seluruh dunia. Misa rutin diadakan dalam berbagai bahasa.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'id', 'Gereja Kelahiran di Betlehem berdiri di atas gua yang oleh tradisi Kristen dihormati sejak abad ke-2 sebagai tempat kelahiran Yesus. Ini adalah salah satu gereja tertua yang terus digunakan di dunia dan merupakan Situs Warisan Dunia UNESCO.', 'Basilika pertama ditugaskan oleh Kaisar Konstantinus dan ibunya Helena sekitar tahun 327 M. Setelah rusak pada abad ke-6, Kaisar Yustinianus membangunnya kembali dalam skala yang lebih besar, dan sebagian besar gereja saat ini berasal dari pembangunan kembali tersebut. Mozaik dan tiang berlukis dari era Perang Salib masih bertahan di dalamnya.', 'Gereja ini digunakan bersama oleh komunitas Ortodoks Yunani, Katolik Roma (Fransiskan), dan Apostolik Armenia di bawah pengaturan Status Quo bersejarah. Keluarga Kristen setempat di Betlehem beribadah di sini bersama para peziarah dari seluruh dunia, terutama pada saat Natal.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'id', 'Gereja Makam Kudus di Kota Tua Yerusalem berisi dua situs tersuci dalam agama Kristen: Golgota, tempat Yesus disalibkan, dan makam tempat Ia dikuburkan dan bangkit kembali, menurut tradisi.', 'Kaisar Konstantinus membangun gereja pertama di sini pada abad ke-4; gereja ini ditahbiskan pada tahun 335 M. Gereja ini dihancurkan pada tahun 1009 dan dibangun kembali pada abad ke-11, dan pasukan Salib memberikan sebagian besar bentuknya yang sekarang pada abad ke-12. Edikula di atas makam direstorasi pada tahun 2016–2017.', 'Perawatan gereja ini dibagi bersama oleh gereja Ortodoks Yunani, Katolik Roma (Fransiskan), dan Apostolik Armenia, dengan komunitas Koptik, Etiopia, dan Ortodoks Suriah yang juga memiliki kapel masing-masing, di bawah Status Quo tahun 1852. Pintunya dibuka setiap pagi oleh keluarga Muslim yang telah menyimpan kunci selama berabad-abad.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
