INSERT INTO church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'ka', 'ხარების ბაზილიკა კათოლიკური ტაძარია ისრაელის ქალაქ ნაზარეთში. ის ახლო აღმოსავლეთის ერთ-ერთი უდიდესი ტაძარია და დგას იმ ადგილას, სადაც, გადმოცემის თანახმად, მთავარანგელოზ გაბრიელმა ქალწულ მარიამს ახარა, რომ იგი იესოს შობდა.', 'ამჟამინდელი ბაზილიკა 1969 წელს აშენდა იტალიელი არქიტექტორის, ჯოვანი მუციოს პროექტით. ის აღმართულია ბიზანტიური და ჯვაროსნული ხანის ადრინდელი ეკლესიების ნანგრევებზე. ეს ადგილი უძველესი დროიდან ქრისტიან მომლოცველთა სალოცავია.', 'ტაძარი ემსახურება ნაზარეთის ადგილობრივ კათოლიკურ თემს და მასპინძლობს მომლოცველებს მთელი მსოფლიოდან. წირვა რეგულარულად აღევლინება რამდენიმე ენაზე.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'ka', 'ბეთლემის ქრისტეს შობის ტაძარი აღმართულია გამოქვაბულზე, რომელსაც ქრისტიანული გადმოცემა II საუკუნიდან პატივს მიაგებს, როგორც იესოს შობის ადგილს. ის მსოფლიოს ერთ-ერთი უძველესი მუდმივად მოქმედი ტაძარია და შეტანილია იუნესკოს მსოფლიო მემკვიდრეობის ძეგლთა ნუსხაში.', 'პირველი ბაზილიკა დაახლოებით ახ. წ. 327 წელს აიგო იმპერატორ კონსტანტინესა და მისი დედის, ელენეს ბრძანებით. VI საუკუნეში დაზიანების შემდეგ იმპერატორ იუსტინიანემ ის უფრო დიდი მასშტაბით აღადგინა და დღევანდელი ტაძრის დიდი ნაწილი სწორედ ამ აღდგენის პერიოდით თარიღდება. ტაძრის შიგნით დღემდეა შემორჩენილი ჯვაროსანთა ეპოქის მოზაიკები და მოხატული სვეტები.', 'ისტორიული სტატუს-კვოს შესაბამისად, ტაძარს ერთობლივად განაგებენ ბერძნული მართლმადიდებლური, რომაულ-კათოლიკური (ფრანცისკელები) და სომხური სამოციქულო თემები. ბეთლემის ადგილობრივი ქრისტიანი ოჯახები აქ ლოცულობენ მთელი მსოფლიოდან ჩამოსულ მომლოცველებთან ერთად, განსაკუთრებით შობის დღესასწაულზე.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'ka', 'იერუსალიმის ძველ ქალაქში მდებარე უფლის საფლავის ტაძარი ქრისტიანობის ორ უდიდეს სიწმინდეს მოიცავს: გოლგოთას, სადაც იესო ჯვარს აცვეს, და საფლავს, სადაც, გადმოცემის თანახმად, იგი დაკრძალეს და საიდანაც მკვდრეთით აღდგა.', 'პირველი ტაძარი აქ იმპერატორ კონსტანტინემ IV საუკუნეში ააგო; ის ახ. წ. 335 წელს აკურთხეს. 1009 წელს ტაძარი დაანგრიეს, XI საუკუნეში აღადგინეს, XII საუკუნეში კი ჯვაროსნებმა მას დიდწილად დღევანდელი სახე მისცეს. უფლის საფლავზე აღმართულ კუვუკლიას 2016–2017 წლებში რესტავრაცია ჩაუტარდა.', 'ტაძარზე ერთობლივად ზრუნავენ ბერძნული მართლმადიდებლური, რომაულ-კათოლიკური (ფრანცისკელები) და სომხური სამოციქულო ეკლესიები, ხოლო საკუთარი სამლოცველოები აქვთ ასევე კოპტურ, ეთიოპიურ და სირიულ მართლმადიდებლურ თემებს. ეს წესრიგი განსაზღვრულია 1852 წლის სტატუს-კვოთი. ტაძრის კარს ყოველ დილას აღებენ მუსლიმი ოჯახები, რომლებიც საუკუნეების განმავლობაში ინახავენ მის გასაღებებს.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
