INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'ka', 'ფართომასშტაბიანი ინიციატივა ისრაელსა და მიმდებარე რეგიონებში ქრისტიანული მემკვიდრეობის ძეგლების, არტეფაქტებისა და ხელნაწერების ფოტოგადაღების, სკანირებისა და დოკუმენტირებისთვის. ეს ციფრული არქივი მკვლევრებისა და მომავალი თაობებისთვის შეინახავს ფასდაუდებელ ისტორიულ წყაროებს.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'short_description', 'ka', 'ქრისტიანული მემკვიდრეობის ძეგლების ციფრული დოკუმენტირება მთელ წმინდა მიწაზე.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
