INSERT INTO church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'ko', '주님 탄생 예고 대성당은 이스라엘 나자렛에 위치한 가톨릭 교회입니다. 중동에서 가장 큰 교회 중 하나이며, 대천사 가브리엘이 마리아에게 예수를 잉태할 것이라고 알린 전통적인 장소를 기념합니다.', '현재의 대성당은 1969년에 이탈리아 건축가 조반니 무치오의 설계로 건립되었습니다. 이전의 비잔틴 및 십자군 시대 교회 유적 위에 세워졌습니다. 이곳은 고대부터 그리스도교 순례지로 여겨져 왔습니다.', '이 교회는 나자렛의 지역 가톨릭 공동체를 섬기며 전 세계에서 온 순례자들을 맞이합니다. 여러 언어로 정기적인 미사가 봉헌됩니다.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'ko', '베들레헴에 있는 예수 탄생 교회는 그리스도교 전통에서 2세기부터 예수님의 탄생지로 공경해 온 동굴 위에 세워져 있습니다. 세계에서 가장 오래도록 계속 사용되어 온 교회 중 하나이며 유네스코 세계문화유산입니다.', '최초의 대성당은 서기 327년경 콘스탄티누스 황제와 그의 어머니 헬레나에 의해 건립되었습니다. 6세기에 훼손된 후 유스티니아누스 황제가 더 큰 규모로 재건했으며, 오늘날 교회의 많은 부분이 이 재건 당시의 모습입니다. 십자군 시대의 모자이크와 채색 기둥이 내부에 여전히 남아 있습니다.', '이 교회는 역사적인 현상 유지 협정 아래 그리스 정교회, 로마 가톨릭(프란치스코회), 아르메니아 사도교회 공동체가 함께 관리합니다. 베들레헴의 지역 그리스도교 가정들은 특히 성탄절에 전 세계에서 온 순례자들과 함께 이곳에서 예배를 드립니다.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'ko', '예루살렘 구시가지에 있는 성묘 교회에는 그리스도교의 가장 거룩한 두 장소가 있습니다. 예수님이 십자가에 못 박히신 골고다와, 전통에 따르면 그분이 묻히고 부활하신 무덤입니다.', '콘스탄티누스 황제가 4세기에 이곳에 최초의 교회를 세웠으며, 335년에 봉헌되었습니다. 1009년에 파괴되었다가 11세기에 재건되었고, 12세기에 십자군이 현재의 모습을 크게 형성했습니다. 무덤 위의 에디큘(성작은집)은 2016~2017년에 복원되었습니다.', '이 교회의 관리는 그리스 정교회, 로마 가톨릭(프란치스코회), 아르메니아 사도교회가 공동으로 맡고 있으며, 콥트, 에티오피아, 시리아 정교회 공동체도 1852년의 현상 유지 협정에 따라 각각 경당을 소유하고 있습니다. 문은 수 세기 동안 열쇠를 지켜온 무슬림 가문이 매일 아침 엽니다.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
