INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'ko', '이스라엘 및 주변 지역의 그리스도교 유산지, 유물, 사본을 촬영, 스캔, 기록하는 종합 사업입니다. 이 디지털 아카이브는 연구자와 후대를 위해 귀중한 역사적 기록을 보존할 것입니다.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'short_description', 'ko', '성지 전역의 그리스도교 유산지를 디지털로 기록하는 사업.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
